var DATA = {"mode": "dims", "w": 20, "d": 6, "h": 16, "n": 64};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="dims"){
  show("Cabinet",DATA.w+" x "+DATA.d+" x "+DATA.h+" in");
  show("Drawers",DATA.n+" polypropylene");
  show("Frame","steel, stackable, wall-mountable");
}else if(m==="drawer"){
  show("Drawer",DATA.w+" x "+DATA.d+" x "+DATA.h+" in");
  show("Holds",DATA.holds);
  show("Dividers",DATA.div?"adjustable, included":"open bin");
}else if(m==="label"){
  show("Label",DATA.what);
  show("Holder","label slot on every drawer front");
