  show("Drawer",DATA.drawer);
  show("Found in",DATA.sec+" seconds");
}else if(m==="inventory"){
  show("Part types tracked",DATA.n);
  show("Method","drawer labels + one index sheet");
}else if(m==="stack"){
  show("Stacking","interlocking frames");
  show("Safe to",DATA.n+" high on a bench");
}else if(m==="wall"){
  show("Wall mount","keyhole slots on the back");
  show("Into","studs or masonry anchors, never drywall alone");
}else if(m==="weight"){
  show("Loaded weight",DATA.kg+" kg");
  show("Advice",DATA.kg>20?"anchor or wall-mount it":"stable on the bench");
}else if(m==="dividers"){
  show("Dividers",DATA.n+" per drawer");
  show("Use","split one drawer into compartments");
}else if(m==="clean"){
  show("Cleaning","drawers pull out fully");
  show("Wash","warm soapy water, air dry");
}else if(m==="expand"){
  show("Growth","add cabinets, keep one master index");
  show("Rule","one part type, one drawer, forever");
}else if(m==="compare"){
  show("Drawer cabinet","tiny parts, visible, labeled");
  show("Bin boxes","bulk parts, stacked storage");
}else if(m==="workflow"){
  console.log("Organization workflow:");
